static int findRecordIndexByName(RandomAccessFile raf, String name) throws IOException {
    long liczbaRekordow = raf.length() / RECORD_SIZE;
    for (int i = 0; i < liczbaRekordow; i++) {
        raf.seek((long) i * RECORD_SIZE);
        byte[] buf = new byte[NAME_BYTES];
        raf.readFully(buf);
        String nazwa = new String(buf, StandardCharsets.UTF_8).strip();
        if (nazwa.equals(name)) return i;
    }
    return -1;
}

