static int binarySearchByPrice(RandomAccessFile raf, int targetPrice) throws IOException {
    int low = 0, high = (int) (raf.length() / RECORD_SIZE) - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        raf.seek((long) mid * RECORD_SIZE + NAME_BYTES);
        int cena = raf.readInt();
        if (cena == targetPrice) return mid;
        else if (cena < targetPrice) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

