static class SimpleFixedDb {
    private final RandomAccessFile raf;
    SimpleFixedDb(File f) throws IOException { raf = new RandomAccessFile(f, "rw"); }

    void insert(String name, int price) throws IOException {
        raf.seek(raf.length());
        raf.write(String.format("%-15s", name).getBytes(StandardCharsets.UTF_8));
        raf.writeInt(price);
    }

    void update(int index, String name, int price) throws IOException {
        raf.seek((long) index * RECORD_SIZE);
        raf.write(String.format("%-15s", name).getBytes(StandardCharsets.UTF_8));
        raf.writeInt(price);
    }

    void delete(int index) throws IOException {
        update(index, "", 0);
    }

    void close() throws IOException { raf.close(); }
}

Deque<Integer> freeList = new ArrayDeque<>();

void delete(int index) throws IOException {
    update(index, "", 0);
    freeList.push(index);
}

void insert(String name, int price) throws IOException {
    if (!freeList.isEmpty()) {
        update(freeList.pop(), name, price);
    } else {
        raf.seek(raf.length());
        raf.write(String.format("%-15s", name).getBytes(StandardCharsets.UTF_8));
        raf.writeInt(price);
    }
}

