static void convertToFixedRecords(Path textFile, Path binaryFile, int fixedLength) throws IOException {
    List<String> linie = Files.readAllLines(textFile);
    try (RandomAccessFile raf = new RandomAccessFile(binaryFile.toFile(), "rw")) {
        for (String linia : linie) {
            String przyciete = linia.length() > fixedLength ? linia.substring(0, fixedLength) : linia;
            raf.write(String.format("%-" + fixedLength + "s", przyciete).getBytes(StandardCharsets.UTF_8));
        }
    }
}

static byte checksum(byte[] dane) {
    byte suma = 0;
    for (byte b : dane) suma ^= b;
    return suma;
}

