static List<Record> readPage(RandomAccessFile raf, int pageNumber, int pageSize) throws IOException {
    List<Record> wynik = new ArrayList<>();
    long start = (long) pageNumber * pageSize;
    raf.seek(start * RECORD_SIZE);
    long liczbaRekordow = raf.length() / RECORD_SIZE;
    for (int i = 0; i < pageSize && start + i < liczbaRekordow; i++) {
        wynik.add(readRecord(raf, NAME_BYTES));
    }
    return wynik;
}

static void compact(Path sourceFile, Path targetFile, int recordSizeWithFlag) throws IOException {
    try (RandomAccessFile in = new RandomAccessFile(sourceFile.toFile(), "r");
         RandomAccessFile out = new RandomAccessFile(targetFile.toFile(), "rw")) {
        long liczbaRekordow = in.length() / recordSizeWithFlag;
        for (long i = 0; i < liczbaRekordow; i++) {
            in.seek(i * recordSizeWithFlag);
            byte[] rekord = new byte[recordSizeWithFlag];
            in.readFully(rekord);
            byte flaga = rekord[rekord.length - 1];
            if (flaga == 0) {
                out.write(rekord);
            }
        }
    }
}

