static class KeyValueStore {
    private static final int KEY_SIZE = 10, VALUE_SIZE = 50, SLOT_SIZE = KEY_SIZE + VALUE_SIZE;
    private final RandomAccessFile raf;
    private final Map<String, Integer> index = new HashMap<>();
    private final Deque<Integer> freeSlots = new ArrayDeque<>();

    KeyValueStore(File f) throws IOException { raf = new RandomAccessFile(f, "rw"); }

    void put(String key, String value) throws IOException {
        int slot = index.containsKey(key) ? index.get(key)
                : !freeSlots.isEmpty() ? freeSlots.pop()
                : (int) (raf.length() / SLOT_SIZE);
        raf.seek((long) slot * SLOT_SIZE);
        raf.write(String.format("%-10s", key).getBytes(StandardCharsets.UTF_8));
        raf.write(String.format("%-50s", value).getBytes(StandardCharsets.UTF_8));
        index.put(key, slot);
    }

    String get(String key) throws IOException {
        Integer slot = index.get(key);
        if (slot == null) return null;
        raf.seek((long) slot * SLOT_SIZE + KEY_SIZE);
        byte[] buf = new byte[VALUE_SIZE];
        raf.readFully(buf);
        return new String(buf, StandardCharsets.UTF_8).strip();
    }

    void delete(String key) {
        Integer slot = index.remove(key);
        if (slot != null) freeSlots.push(slot);
    }
}
